-- Contrats, lot 2 (ADR 0034, stories F4, F5, F6) : modèles de contrats versionnés, bibliothèque de clauses,
-- catalogue des services et honoraires, taux de taxes par province, tableau des services d'un contrat.
--
-- Lecture : tout le personnel actif (les modèles en brouillon : firm_admin seulement). Écriture : firm_admin.
-- Un modèle se crée et se modifie dans l'éditeur des contrats : « Enregistrer comme modèle », ou un brouillon
-- de modèle ouvert depuis la bibliothèque, puis « Publier une nouvelle version » (fonctions ci-dessous).
-- Les taux de taxes de départ sont à VÉRIFIER par le cabinet (needs_verification) : la plateforme ne tranche
-- pas un chiffre fiscal.

-- ---------------------------------------------------------------------------------------------
-- 1. Modèles
-- ---------------------------------------------------------------------------------------------
create table public.contract_templates (
  id              uuid primary key default gen_random_uuid(),
  name            text not null check (length(btrim(name)) between 1 and 200 and name !~ '[[:cntrl:]]'),
  description     text check (description is null or (length(description) <= 1000 and description !~ '[[:cntrl:]]')),
  domain          text not null default 'other' check (domain in ('immigration', 'legal', 'business', 'advisory', 'other')),
  language        text not null check (language in ('fr', 'en')),
  -- Mode de signature prévu : Clio (option A), acceptation dans le portail, ou au choix (décision du 2026-10-19).
  signing         text not null default 'clio' check (signing in ('clio', 'portal', 'both')),
  status          text not null default 'draft' check (status in ('draft', 'published', 'archived')),
  -- Texte à faire valider par un avocat (ex. traduction) : jamais utilisable tant qu'il n'est pas publié.
  needs_review    boolean not null default false,
  current_version int not null default 0 check (current_version >= 0),
  is_mock         boolean not null default false,
  created_by      uuid references public.profiles(id) on delete set null default auth.uid(),
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);
create trigger contract_templates_updated_at before update on public.contract_templates
  for each row execute function private.set_updated_at();

create table public.contract_template_versions (
  template_id uuid not null references public.contract_templates(id) on delete restrict,
  version     int  not null check (version >= 1),
  sections    jsonb not null check (jsonb_typeof(sections) = 'array' and pg_column_size(sections) <= 600000),
  line_items  jsonb not null default '[]' check (jsonb_typeof(line_items) = 'array' and jsonb_array_length(line_items) <= 100),
  created_by  uuid references public.profiles(id) on delete set null default auth.uid(),
  created_at  timestamptz not null default now(),
  primary key (template_id, version)
);

alter table public.contract_templates enable row level security;
alter table public.contract_template_versions enable row level security;
create policy contract_templates_select on public.contract_templates for select to authenticated
  using (private.is_staff() and (status = 'published' or private.is_firm_admin()));
create policy contract_templates_update on public.contract_templates for update to authenticated
  using (private.is_firm_admin()) with check (private.is_firm_admin());
create policy contract_template_versions_select on public.contract_template_versions for select to authenticated
  using (exists (select 1 from public.contract_templates t where t.id = template_id
                  and private.is_staff() and (t.status = 'published' or private.is_firm_admin())));
revoke all on public.contract_templates, public.contract_template_versions from anon, authenticated;
grant select on public.contract_templates, public.contract_template_versions to authenticated;
-- La version et le contenu ne s'écrivent que par les fonctions de publication.
grant update (name, description, domain, signing, status) on public.contract_templates to authenticated;

-- ---------------------------------------------------------------------------------------------
-- 2. Contrats : modèle d'origine, brouillon de modèle, province du client (taxes)
-- ---------------------------------------------------------------------------------------------
alter table public.contracts
  add column template_id uuid references public.contract_templates(id) on delete set null,
  add column template_version int,
  -- Brouillon servant à modifier un modèle (firm_admin) : hors de la liste des contrats.
  add column template_draft boolean not null default false,
  add column client_province text check (client_province is null
                                         or client_province in ('NB', 'NS', 'ON', 'QC', 'PE', 'NL', 'other'));
grant insert (template_id, template_version, template_draft, client_province) on public.contracts to authenticated;
grant update (client_province) on public.contracts to authenticated;

create or replace function private.guard_contract_template()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if new.template_draft and auth.uid() is not null and not private.is_firm_admin() then
    raise exception 'template draft: firm_admin only' using errcode = '42501';
  end if;
  if new.template_draft and new.template_id is null then
    raise exception 'template draft without template' using errcode = '23514';
  end if;
  if new.template_id is not null and not exists (
       select 1 from public.contract_template_versions v
         join public.contract_templates t on t.id = v.template_id
        where v.template_id = new.template_id and v.version = new.template_version
          and (t.status = 'published' or new.template_draft)) then
    raise exception 'invalid template' using errcode = '23514';
  end if;
  return new;
end $$;
create trigger contracts_guard_template before insert on public.contracts
  for each row execute function private.guard_contract_template();

-- ---------------------------------------------------------------------------------------------
-- 3. Tableau des services d'un contrat
-- ---------------------------------------------------------------------------------------------
create table public.service_catalog (
  id             uuid primary key default gen_random_uuid(),
  name_fr        text not null check (length(btrim(name_fr)) between 1 and 200 and name_fr !~ '[[:cntrl:]]'),
  name_en        text not null check (length(btrim(name_en)) between 1 and 200 and name_en !~ '[[:cntrl:]]'),
  description_fr text check (description_fr is null or length(description_fr) <= 1000),
  description_en text check (description_en is null or length(description_en) <= 1000),
  domain         text not null default 'other' check (domain in ('immigration', 'legal', 'business', 'advisory', 'other')),
  pricing        text not null check (pricing in ('flat', 'hourly')),
  amount         numeric(12, 2) not null check (amount >= 0 and amount < 10000000),
  is_active      boolean not null default true,
  position       smallint not null default 0,
  is_mock        boolean not null default false,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);
create trigger service_catalog_updated_at before update on public.service_catalog
  for each row execute function private.set_updated_at();

create table public.contract_line_items (
  id          uuid primary key default gen_random_uuid(),
  contract_id uuid not null references public.contracts(id) on delete restrict,
  position    smallint not null default 0 check (position between 0 and 99),
  service_id  uuid references public.service_catalog(id) on delete set null,
  description text not null check (length(btrim(description)) between 1 and 300 and description !~ '[[:cntrl:]]'),
  pricing     text not null default 'flat' check (pricing in ('flat', 'hourly')),
  quantity    numeric(10, 2) not null default 1 check (quantity > 0 and quantity <= 10000),
  unit_price  numeric(12, 2) not null check (unit_price >= 0 and unit_price < 10000000),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index contract_line_items_contract_idx on public.contract_line_items (contract_id, position);
create trigger contract_line_items_updated_at before update on public.contract_line_items
  for each row execute function private.set_updated_at();

-- Taux de taxes par province, avec date d'effet ; `rate` en pour cent (9.975 = 9,975 %).
create table public.tax_rates (
  id                 uuid primary key default gen_random_uuid(),
  province           text not null check (province in ('NB', 'NS', 'ON', 'QC', 'PE', 'NL', 'other')),
  tax_code           text not null check (tax_code in ('HST', 'GST', 'QST', 'PST')),
  rate               numeric(6, 3) not null check (rate >= 0 and rate <= 30),
  effective_from     date not null,
  effective_to       date check (effective_to is null or effective_to > effective_from),
  needs_verification boolean not null default true,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);
create trigger tax_rates_updated_at before update on public.tax_rates
  for each row execute function private.set_updated_at();

create or replace function private.contract_line_count(p_contract uuid)
returns int language sql stable security definer set search_path = '' as $$
  select count(*)::int from public.contract_line_items l where l.contract_id = p_contract
$$;
revoke all on function private.contract_line_count(uuid) from public;
grant execute on function private.contract_line_count(uuid) to authenticated, service_role;

alter table public.service_catalog enable row level security;
alter table public.contract_line_items enable row level security;
alter table public.tax_rates enable row level security;
create policy service_catalog_select on public.service_catalog for select to authenticated using (private.is_staff());
create policy service_catalog_insert on public.service_catalog for insert to authenticated with check (private.is_firm_admin());
create policy service_catalog_update on public.service_catalog for update to authenticated
  using (private.is_firm_admin()) with check (private.is_firm_admin());
create policy tax_rates_select on public.tax_rates for select to authenticated using (private.is_staff());
create policy tax_rates_insert on public.tax_rates for insert to authenticated with check (private.is_firm_admin());
create policy tax_rates_update on public.tax_rates for update to authenticated
  using (private.is_firm_admin()) with check (private.is_firm_admin());
create policy contract_line_items_select on public.contract_line_items for select to authenticated
  using (exists (select 1 from public.contracts c where c.id = contract_id
                  and private.can_access_contract(c.matter_id, c.created_by)));
create policy contract_line_items_insert on public.contract_line_items for insert to authenticated
  with check (private.can_edit_contract(contract_id) and private.contract_line_count(contract_id) < 100);
create policy contract_line_items_update on public.contract_line_items for update to authenticated
  using (private.can_edit_contract(contract_id)) with check (private.can_edit_contract(contract_id));
create policy contract_line_items_delete on public.contract_line_items for delete to authenticated
  using (private.can_edit_contract(contract_id));

revoke all on public.service_catalog, public.contract_line_items, public.tax_rates from anon, authenticated;
grant select on public.service_catalog, public.contract_line_items, public.tax_rates to authenticated;
grant insert (name_fr, name_en, description_fr, description_en, domain, pricing, amount, is_active, position)
  on public.service_catalog to authenticated;
grant update (name_fr, name_en, description_fr, description_en, domain, pricing, amount, is_active, position)
  on public.service_catalog to authenticated;
grant insert (province, tax_code, rate, effective_from, effective_to, needs_verification) on public.tax_rates to authenticated;
grant update (rate, effective_from, effective_to, needs_verification) on public.tax_rates to authenticated;
grant insert (id, contract_id, position, service_id, description, pricing, quantity, unit_price)
  on public.contract_line_items to authenticated;
grant update (position, service_id, description, pricing, quantity, unit_price) on public.contract_line_items to authenticated;
grant delete on public.contract_line_items to authenticated;

-- ---------------------------------------------------------------------------------------------
-- 4. Clauses (historique des versions)
-- ---------------------------------------------------------------------------------------------
create table public.contract_clauses (
  id         uuid primary key default gen_random_uuid(),
  title      text not null check (length(btrim(title)) between 1 and 200 and title !~ '[[:cntrl:]]'),
  language   text not null check (language in ('fr', 'en')),
  domain     text not null default 'other' check (domain in ('immigration', 'legal', 'business', 'advisory', 'other')),
  -- Texte simple : paragraphes, et « - » en début de ligne pour une liste (converti à l'insertion).
  body       text not null check (length(btrim(body)) between 1 and 20000
                                  and replace(replace(body, chr(10), ''), chr(13), '') !~ '[[:cntrl:]]'),
  is_active  boolean not null default true,
  version    int not null default 1,
  created_by uuid references public.profiles(id) on delete set null default auth.uid(),
  updated_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create trigger contract_clauses_updated_at before update on public.contract_clauses
  for each row execute function private.set_updated_at();

create table public.contract_clause_history (
  id         bigint generated always as identity primary key,
  clause_id  uuid not null references public.contract_clauses(id) on delete restrict,
  version    int not null,
  title      text not null,
  body       text not null,
  changed_by uuid references public.profiles(id) on delete set null,
  changed_at timestamptz not null default now()
);

create or replace function private.version_contract_clause()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  new.updated_by := coalesce(auth.uid(), new.updated_by);
  new.created_by := old.created_by;
  if (new.title, new.body) is distinct from (old.title, old.body) then
    insert into public.contract_clause_history (clause_id, version, title, body, changed_by)
    values (old.id, old.version, old.title, old.body, auth.uid());
    new.version := old.version + 1;
  else
    new.version := old.version;
  end if;
  return new;
end $$;
create trigger contract_clauses_version before update on public.contract_clauses
  for each row execute function private.version_contract_clause();

alter table public.contract_clauses enable row level security;
alter table public.contract_clause_history enable row level security;
create policy contract_clauses_select on public.contract_clauses for select to authenticated using (private.is_staff());
create policy contract_clauses_insert on public.contract_clauses for insert to authenticated with check (private.is_firm_admin());
create policy contract_clauses_update on public.contract_clauses for update to authenticated
  using (private.is_firm_admin()) with check (private.is_firm_admin());
create policy contract_clause_history_select on public.contract_clause_history for select to authenticated
  using (private.is_firm_admin());
revoke all on public.contract_clauses, public.contract_clause_history from anon, authenticated;
grant select on public.contract_clauses, public.contract_clause_history to authenticated;
grant insert (title, language, domain, body, is_active) on public.contract_clauses to authenticated;
grant update (title, language, domain, body, is_active) on public.contract_clauses to authenticated;

-- ---------------------------------------------------------------------------------------------
-- 5. Journal : changements de la bibliothèque (sans contenu)
-- ---------------------------------------------------------------------------------------------
create or replace function private.audit_contract_library()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  perform audit.record(
    case tg_table_name
      when 'contract_templates' then 'contract_template.'
      when 'contract_clauses' then 'contract_clause.'
      when 'service_catalog' then 'service_catalog.'
      else 'tax_rate.' end || case tg_op when 'INSERT' then 'created' else 'updated' end,
    tg_table_name, new.id::text, null, '{}'::jsonb);
  return null;
end $$;
create trigger contract_templates_audit after update on public.contract_templates
  for each row execute function private.audit_contract_library();
create trigger contract_clauses_audit after insert or update on public.contract_clauses
  for each row execute function private.audit_contract_library();
create trigger service_catalog_audit after insert or update on public.service_catalog
  for each row execute function private.audit_contract_library();
create trigger tax_rates_audit after insert or update on public.tax_rates
  for each row execute function private.audit_contract_library();
revoke all on function private.guard_contract_template(), private.version_contract_clause(),
  private.audit_contract_library() from public;

-- ---------------------------------------------------------------------------------------------
-- 6. Publication des modèles (firm_admin)
-- ---------------------------------------------------------------------------------------------
-- Copie des sections et du tableau des services d'un contrat (format d'une version de modèle).
create or replace function private.contract_snapshot(p_contract uuid)
returns table (sections jsonb, line_items jsonb)
language sql stable security definer set search_path = '' as $$
  select
    coalesce((select jsonb_agg(jsonb_build_object('position', s.position, 'title', s.title, 'body', s.body,
                                                  'ai_assisted', s.ai_assisted) order by s.position, s.created_at)
                from public.contract_sections s where s.contract_id = p_contract), '[]'::jsonb),
    coalesce((select jsonb_agg(jsonb_build_object('description', l.description, 'pricing', l.pricing,
                                                  'quantity', l.quantity::text, 'unit_price', l.unit_price::text,
                                                  'service_id', l.service_id) order by l.position, l.created_at)
                from public.contract_line_items l where l.contract_id = p_contract), '[]'::jsonb)
$$;
revoke all on function private.contract_snapshot(uuid) from public;

-- Nouveau modèle à partir d'un contrat que l'on voit (publié tout de suite, version 1).
create or replace function public.contract_template_from_contract(p_contract uuid, p_name text, p_domain text,
                                                                  p_signing text, p_description text default null)
returns uuid language plpgsql volatile security definer set search_path = '' as $$
declare v_id uuid; v_lang text; v public.contracts%rowtype;
begin
  if not private.is_firm_admin() then
    raise exception 'firm_admin only' using errcode = '42501';
  end if;
  select * into v from public.contracts c where c.id = p_contract;
  if not found or not private.can_access_contract(v.matter_id, v.created_by) then
    raise exception 'not found' using errcode = 'P0002';
  end if;
  insert into public.contract_templates (name, description, domain, language, signing, status, current_version)
  values (p_name, nullif(btrim(coalesce(p_description, '')), ''), coalesce(p_domain, 'other'), v.language,
          coalesce(p_signing, 'clio'), 'published', 1)
  returning id into v_id;
  insert into public.contract_template_versions (template_id, version, sections, line_items)
  select v_id, 1, s.sections, s.line_items from private.contract_snapshot(p_contract) s;
  perform audit.record('contract_template.created', 'contract_templates', v_id::text, null,
                       jsonb_build_object('from_contract', p_contract));
  return v_id;
end $$;

-- Publier le brouillon d'un modèle (contrat `template_draft`) comme nouvelle version ; valide aussi un
-- modèle « à faire valider » (traduction).
create or replace function public.contract_template_publish(p_contract uuid)
returns int language plpgsql volatile security definer set search_path = '' as $$
declare v public.contracts%rowtype; v_version int;
begin
  if not private.is_firm_admin() then
    raise exception 'firm_admin only' using errcode = '42501';
  end if;
  select * into v from public.contracts c where c.id = p_contract and c.template_draft;
  if not found then
    raise exception 'not found' using errcode = 'P0002';
  end if;
  select t.current_version + 1 into v_version from public.contract_templates t where t.id = v.template_id for update;
  insert into public.contract_template_versions (template_id, version, sections, line_items)
  select v.template_id, v_version, s.sections, s.line_items from private.contract_snapshot(p_contract) s;
  update public.contract_templates t
     set current_version = v_version, status = 'published', needs_review = false
   where t.id = v.template_id;
  -- Le brouillon a servi : il est clos.
  update public.contracts c set status = 'cancelled', cancel_reason = 'Publié comme version ' || v_version
   where c.id = p_contract;
  perform audit.record('contract_template.published', 'contract_templates', v.template_id::text, null,
                       jsonb_build_object('version', v_version));
  return v_version;
end $$;

revoke all on function public.contract_template_from_contract(uuid, text, text, text, text),
  public.contract_template_publish(uuid) from public, anon;
grant execute on function public.contract_template_from_contract(uuid, text, text, text, text),
  public.contract_template_publish(uuid) to authenticated;

