insert into public.contract_template_versions (template_id, version, sections, line_items)
  values ('10000000-0000-4000-8000-0000000c0001', 1, $json$[{"position": 0, "title": "Introduction", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Thank you for choosing Lex Canada Law to assist you with your legal matters. These general terms explain the framework within which our firm provides its services. They supplement the engagement letter, fee agreement, or any other specific arrangement entered into with the client. In the event of any inconsistency, the terms of the engagement letter or specific arrangement prevail."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Client: "}, {"type": "field", "attrs": {"key": "client.name"}}, {"type": "text", "text": " · Matter: "}, {"type": "field", "attrs": {"key": "matter.number"}}, {"type": "text", "text": " · Responsible lawyer: "}, {"type": "field", "attrs": {"key": "lawyer.name"}}]}]}, "ai_assisted": false}, {"position": 1, "title": "1. The client", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "When a company, corporation, organization, or other entity retains Lex Canada Law, our client is the organization itself."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Unless otherwise agreed in writing, our engagement does not create a lawyer-client relationship with the shareholders, directors, officers, employees, partners, subsidiaries, affiliates, or representatives of the organization."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "We may take instructions from the persons the organization designates, or who reasonably appear to be authorized to act on its behalf. The client must promptly inform us of any change in the persons authorized to give instructions."}]}]}, "ai_assisted": false}, {"position": 2, "title": "2. Our legal team", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A responsible lawyer is assigned to supervise the engagement and coordinate the services."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Depending on the nature of the matter, Lex Canada Law may involve other lawyers, paralegals, consultants, professionals, or specialized providers. Their involvement depends in particular on:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "the complexity of the matter;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "the skills required;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "the applicable deadlines;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "the availability of resources;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "the need to draw on external expertise."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "All professionals working on the file are bound by the applicable obligations of confidentiality and professional secrecy."}]}]}, "ai_assisted": false}, {"position": 3, "title": "3. Scope of the engagement", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "The nature and limits of our involvement are set out in the engagement letter, the fee agreement, or the written communications exchanged with the client."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "We will not substantially expand the engagement without the client's instructions or authorization."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Unless expressly agreed, our involvement does not automatically include:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "tax or accounting advice;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "the financial evaluation of a transaction;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "investment advice;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "the laws of a foreign jurisdiction;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "ongoing monitoring of legislative changes;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "services not expressly set out in the engagement."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The client must obtain advice from its accountants, tax specialists, brokers, consultants, or other professionals where the situation requires."}]}]}, "ai_assisted": false}, {"position": 4, "title": "4. Client responsibilities", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "The client agrees to:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "provide us with complete, accurate, and up-to-date information;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "promptly send us the necessary documents;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "notify us of any important deadline;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "inform us of any change that may affect the engagement;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "preserve relevant documents, emails, and evidence;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "cooperate reasonably with our team;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "review the documents provided to it;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "promptly notify us of any error or concern."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Lex Canada Law cannot be held responsible for consequences arising from information that is incomplete, inaccurate, late, or withheld by the client or by a person acting on its behalf."}]}]}, "ai_assisted": false}, {"position": 5, "title": "5. No guarantee of outcome", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Lex Canada Law undertakes to provide its services with competence, diligence, and professionalism. However, no specific outcome can be guaranteed. The decisions of courts, government authorities, administrative bodies, and opposing parties remain beyond our control."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The estimates, opinions, and strategies communicated to the client represent our professional assessment at the time they are made. They do not constitute a promise of results."}]}]}, "ai_assisted": false}, {"position": 6, "title": "6. Conflicts of interest", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Before accepting an engagement, Lex Canada Law may carry out the checks necessary to determine whether a conflict of interest exists."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Our firm represents several clients, some of whom may operate in the same sector or have commercial interests different from those of the client."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Subject to our professional obligations, representing one organization does not automatically prevent us from representing other clients in separate matters."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "No confidential information belonging to the client will be used or disclosed for the benefit of another client without authorization or an applicable legal basis."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "If an actual or potential conflict arises, we will take the measures required in accordance with our professional obligations. These may include obtaining consent, implementing protective measures, or terminating the engagement."}]}]}, "ai_assisted": false}, {"position": 7, "title": "7. Fees, retainers, and disbursements", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Fees may be set on the basis of:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "an hourly rate;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "a fixed amount;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "a periodic retainer;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "a specific arrangement;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "a combination of these methods."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The applicable billing method is set out in the engagement letter or the fee agreement."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Budget estimates are provided for guidance only, except where a fixed price is expressly agreed. They may change if the scope, complexity, timelines, or circumstances of the file change."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The client also remains responsible for applicable taxes and disbursements, including:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "government fees;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "filing or registration fees;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "court fees;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "courier services;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "authorized travel expenses;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "translations;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "expert reports;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "specialized searches;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "third-party services."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Lex Canada Law may request a retainer in trust before beginning or continuing work. The client may be required to replenish this retainer during the engagement."}]}]}, "ai_assisted": false}, {"position": 8, "title": "8. Billing and payment", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Invoices are payable in accordance with the terms indicated on them or in the fee agreement."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "In the event of late payment, Lex Canada Law may, within the limits permitted by professional rules:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "request immediate payment of amounts due;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "require the retainer to be replenished;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "suspend certain work;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "cease to act for the client;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "apply the interest provided for in the applicable agreement."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The end or failure of a transaction, application, or proceeding does not relieve the client of payment for services already rendered and disbursements incurred."}]}]}, "ai_assisted": false}, {"position": 9, "title": "9. Use of technology", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Lex Canada Law may use secure technologies to facilitate the delivery of its services, including:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "client portals;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "electronic file management;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "electronic signatures;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "video conferencing;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "legal research tools;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "document analysis;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "cloud services;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "artificial intelligence technologies."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "These tools are used under the supervision of legal professionals. All legal work intended for the client or a competent authority is subject to appropriate professional review."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "We select our tools with our obligations of confidentiality, security, and protection of personal information in mind."}]}]}, "ai_assisted": false}, {"position": 10, "title": "10. Electronic communications", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Unless instructed otherwise, the client authorizes Lex Canada Law to communicate by email, telephone, video conference, client portal, or other reasonable electronic means."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Electronic communications carry certain risks, including interception, fraud, viruses, misaddressing, and transmission delays."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The client must confirm directly with our firm any unusual instruction, particularly where it concerns:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "a payment;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "a change of banking details;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "a transfer of funds;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "the transmission of highly sensitive information;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "an urgent or unusual request."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Lex Canada Law will never ask the client to change important banking instructions without an appropriate verification mechanism."}]}]}, "ai_assisted": false}, {"position": 11, "title": "11. Confidentiality and personal information", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Lex Canada Law collects, uses, retains, and discloses the information necessary to provide its services, manage the file, and comply with its legal and professional obligations."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Information may be used in particular to:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "verify the client's identity;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "detect conflicts of interest;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "provide the requested services;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "communicate with authorized authorities and parties;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "produce the required documents;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "manage billing and payments;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "meet regulatory requirements."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The processing of personal information is also subject to Lex Canada Law's privacy policy."}]}]}, "ai_assisted": false}, {"position": 12, "title": "12. Termination", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "The client may terminate the engagement by written notice."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Lex Canada Law may also cease to act where professional rules permit, including in cases of:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "conflict of interest;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "loss of trust;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "refusal to cooperate;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "illegal or unethical instructions;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "false or misleading information;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "non-payment of fees;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "reasonable impossibility of continuing the engagement."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Upon termination, unpaid fees, taxes, and disbursements become due."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Unless otherwise agreed, our obligation to act ends when the engagement is completed, the file is closed, or our final invoice is issued. We have no obligation to monitor future changes in the law or to remind the client of deadlines arising after the file is closed."}]}]}, "ai_assisted": false}, {"position": 13, "title": "13. File retention", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "File documents are retained in accordance with applicable legal, professional, and administrative requirements."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "At the end of the retention period, certain documents may be securely destroyed, except where longer retention is required by law or agreed with the client."}]}]}, "ai_assisted": false}, {"position": 14, "title": "14. Governing law", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "These terms are governed by the laws of the Province of Nova Scotia and the federal laws of Canada applicable therein, subject to the professional rules governing the legal services concerned."}]}]}, "ai_assisted": false}, {"position": 15, "title": "Acceptance of these terms", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "By signing an engagement letter, accepting a fee agreement, or asking Lex Canada Law to begin the agreed services, the client acknowledges having read these terms and agrees that they govern the delivery of the services, subject to any specific written agreement. For any question concerning these terms or your file, please contact the lawyer responsible for your engagement."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Client: "}, {"type": "field", "attrs": {"key": "client.name"}}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Date: "}, {"type": "field", "attrs": {"key": "date.today"}}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Signature: ______________________________"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "© 2026 Lex Canada Juris Corp. All rights reserved. Lex Canada Law is a trademark of Lex Canada Juris Corp."}]}]}, "ai_assisted": false}]$json$::jsonb, $json$[]$json$::jsonb);
insert into public.contract_templates (id, name, description, domain, language, signing, status, needs_review, current_version, is_mock)
  values ('10000000-0000-4000-8000-0000000c0002', 'Client Service Terms — Individuals & Families', 'General terms for individuals and families (Lex Canada Law document).', 'legal', 'en', 'portal', 'published', false, 1, false);
insert into public.contract_template_versions (template_id, version, sections, line_items)
  values ('10000000-0000-4000-8000-0000000c0002', 1, $json$[{"position": 0, "title": "Introduction", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Thank you for choosing Lex Canada Law to assist you with your legal matters. These general terms explain the framework within which our firm provides its services. They supplement the engagement letter, fee agreement, or any other specific arrangement entered into with the client. In the event of any inconsistency, the terms of the engagement letter or specific arrangement prevail."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Client: "}, {"type": "field", "attrs": {"key": "client.name"}}, {"type": "text", "text": " · Matter: "}, {"type": "field", "attrs": {"key": "matter.number"}}, {"type": "text", "text": " · Responsible lawyer: "}, {"type": "field", "attrs": {"key": "lawyer.name"}}]}]}, "ai_assisted": false}, {"position": 1, "title": "1. Our commitment to you", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Lex Canada Law supports individuals and families with competence, clarity, respect, and confidentiality. Our role is to explain your options, help you understand the risks, and advance your interests within the engagement entrusted to us."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "You will work with a lawyer responsible for your file. Other professionals may also take part where their expertise is required."}]}]}, "ai_assisted": false}, {"position": 2, "title": "2. Formation of the lawyer-client relationship", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A consultation, an exchange of emails, or the transmission of documents does not automatically mean that Lex Canada Law has agreed to represent you."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The lawyer-client relationship begins only when:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "the firm has confirmed acceptance of the engagement;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "identity and conflict checks have been completed;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "the fee agreement or engagement letter has been accepted;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "the requested retainer, if any, has been paid."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Before this confirmation, you remain responsible for your own deadlines and the protection of your rights."}]}]}, "ai_assisted": false}, {"position": 3, "title": "3. Scope of our involvement", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Our engagement is limited to the services described in your engagement letter or fee agreement."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "For example, an engagement concerning an immigration application does not automatically include:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "an appeal or judicial review;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "a new application after a refusal;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "an unscheduled hearing;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "a matter involving a different family member;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "tax advice;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "a separate civil proceeding."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Any additional service requires new authorization and may result in additional fees."}]}]}, "ai_assisted": false}, {"position": 4, "title": "4. Your cooperation", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "To represent you well, we need complete, accurate information provided on time."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "You must, in particular:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "answer our questions honestly;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "provide all relevant documents;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "inform us of your history and of any prior refusal;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "meet the deadlines communicated;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "review forms and declarations before signing them;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "immediately notify us of any change of address, status, or situation;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "keep the originals of your important documents;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "forward to us any communication received from an authority, court, or opposing party."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Concealing or omitting important information may compromise your file and may require us to cease acting."}]}]}, "ai_assisted": false}, {"position": 5, "title": "5. Immigration services", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "In immigration matters, the client acknowledges that decisions rest in particular with Immigration, Refugees and Citizenship Canada, the Canada Border Services Agency, the Immigration and Refugee Board, the courts, or provincial programs."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Processing times may change and remain beyond the control of Lex Canada Law."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "We cannot guarantee:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "the approval of an application;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "the issuance of a visa or permit;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "obtaining permanent residence;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "the acceptance of an appeal;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "a specific decision date;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "the absence of an interview, investigation, or additional documentary request."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Our responsibility is to prepare, advise, and represent the client in accordance with the agreed engagement."}]}]}, "ai_assisted": false}, {"position": 6, "title": "6. Litigation and proceedings", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "In a contentious matter, outcomes may depend on the evidence, testimony, rules of procedure, the position of the opposing party, and the decision of the court."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The client understands that a proceeding may involve:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "delays;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "additional costs;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "negotiations;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "mediation;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "a hearing;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "an unfavourable decision;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "an award of costs."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "We will advise the client of reasonable options, but the final decision to settle or continue the matter rests with the client."}]}]}, "ai_assisted": false}, {"position": 7, "title": "7. Estate planning", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Wills, powers of attorney, personal directives, and other estate documents are prepared based on the information provided by the client."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The client must inform us of their family situation, assets, obligations, intentions, and any relevant special circumstances."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "After the engagement ends, Lex Canada Law has no obligation to automatically update the documents. The client should request a review after a significant change, including:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "a marriage or separation;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "a birth or adoption;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "a death;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "the acquisition or sale of a significant asset;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "a move to another province or country;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "a significant change in the law."}]}]}]}]}, "ai_assisted": false}, {"position": 8, "title": "8. Fees and disbursements", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Our fees may be fixed or calculated based on the time spent on the file. The applicable method is specified before the engagement begins."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Additional fees may apply if:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "the engagement is expanded;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "new facts arise;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "the client requests urgent handling;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "a hearing or interview becomes necessary;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "additional documents must be prepared;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "a new proceeding is undertaken."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Government, court, administrative, and other disbursements are not included unless otherwise stated."}]}]}, "ai_assisted": false}, {"position": 9, "title": "9. Payment", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A retainer may be required before work begins. Amounts placed in trust are applied to invoices in accordance with applicable rules."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Invoices must be paid according to the agreed terms. A failure to pay may result in the suspension or termination of the engagement, where professional rules permit."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Fees remain payable even if the application is refused, the proceeding fails, or the client decides not to continue the matter."}]}]}, "ai_assisted": false}, {"position": 10, "title": "10. Confidentiality", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Information entrusted to Lex Canada Law is protected by our confidentiality obligations and, where the legal conditions are met, by lawyer-client privilege."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "In a joint engagement — in particular where we represent several members of the same family — information relevant to the file may need to be shared among the clients represented."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "If a conflict arises between clients in a joint engagement, Lex Canada Law may be required to cease representing one or more of the persons concerned."}]}]}, "ai_assisted": false}, {"position": 11, "title": "11. Protection of personal information", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "We collect only the information necessary to provide our services and meet our obligations."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Depending on the file, certain information may be provided to courts, government authorities, experts, translators, or other authorized parties."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "For more information, the client may consult Lex Canada Law's privacy policy."}]}]}, "ai_assisted": false}, {"position": 12, "title": "12. Technology and artificial intelligence", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Lex Canada Law may use technology tools to improve the management and quality of its services, including to:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "manage files;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "communicate with clients;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "conduct legal research;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "analyze or organize documents;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "prepare draft documents;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "obtain electronic signatures."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Any use of a technology tool remains subject to the obligations of confidentiality and professional competence. Documents and legal advice produced with the help of these tools are reviewed by a legal professional before any official use."}]}]}, "ai_assisted": false}, {"position": 13, "title": "13. Communications and security", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "The client authorizes electronic communications to the contact details they provide."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The client must inform Lex Canada Law if an email address or phone number is not secure, is shared with another person, or must not be used to transmit confidential information."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "No payment or change of banking details should be made solely on the basis of an unexpected email. The client must contact the firm directly to verify any unusual financial instruction."}]}]}, "ai_assisted": false}, {"position": 14, "title": "14. Termination", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "The client may terminate the engagement by written notice."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Lex Canada Law may cease to act in accordance with its professional obligations, including in cases of conflict, non-payment, lack of cooperation, loss of trust, or instructions contrary to law."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Fees and disbursements incurred up to the end of the engagement remain payable."}]}]}, "ai_assisted": false}, {"position": 15, "title": "15. File closing and retention", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "At the end of the engagement, Lex Canada Law closes the file and retains the documents in accordance with its retention policy and applicable professional requirements."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Once the file is closed, the firm is not required to monitor future changes in the law, new deadlines, or changes in the client's situation, unless a new engagement is expressly accepted."}]}]}, "ai_assisted": false}, {"position": 16, "title": "16. Governing law", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "These terms are governed by the laws of Nova Scotia and the federal laws of Canada applicable therein, subject to the relevant professional rules."}]}]}, "ai_assisted": false}, {"position": 17, "title": "Acceptance of these terms", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "By signing an engagement letter, accepting a fee agreement, or asking Lex Canada Law to begin the agreed services, the client acknowledges having read these terms and agrees that they govern the delivery of the services, subject to any specific written agreement. For any question concerning these terms or your file, please contact the lawyer responsible for your engagement."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Client: "}, {"type": "field", "attrs": {"key": "client.name"}}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Date: "}, {"type": "field", "attrs": {"key": "date.today"}}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Signature: ______________________________"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "© 2026 Lex Canada Juris Corp. All rights reserved. Lex Canada Law is a trademark of Lex Canada Juris Corp."}]}]}, "ai_assisted": false}]$json$::jsonb, $json$[]$json$::jsonb);
insert into public.contract_templates (id, name, description, domain, language, signing, status, needs_review, current_version, is_mock)
  values ('10000000-0000-4000-8000-0000000c0003', 'Conditions générales de service — Entreprises et organisations', 'Traduction française à faire valider par un avocat avant publication.', 'business', 'fr', 'portal', 'draft', true, 1, false);
insert into public.contract_template_versions (template_id, version, sections, line_items)
  values ('10000000-0000-4000-8000-0000000c0003', 1, $json$[{"position": 0, "title": "Introduction", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Merci d'avoir choisi Lex Canada Law pour vous accompagner dans vos affaires juridiques. Les présentes conditions générales décrivent le cadre dans lequel notre cabinet fournit ses services. Elles complètent la lettre de mandat, la convention d'honoraires ou toute autre entente particulière conclue avec le client. En cas d'incompatibilité, les modalités de la lettre de mandat ou de l'entente particulière prévalent."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Client : "}, {"type": "field", "attrs": {"key": "client.name"}}, {"type": "text", "text": " · Dossier : "}, {"type": "field", "attrs": {"key": "matter.number"}}, {"type": "text", "text": " · Avocat responsable : "}, {"type": "field", "attrs": {"key": "lawyer.name"}}]}]}, "ai_assisted": false}, {"position": 1, "title": "1. Le client", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Lorsqu'une société, une personne morale, une organisation ou toute autre entité retient les services de Lex Canada Law, notre client est l'organisation elle-même."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Sauf entente écrite contraire, notre mandat ne crée pas de relation avocat-client avec les actionnaires, administrateurs, dirigeants, employés, associés, filiales, sociétés affiliées ou représentants de l'organisation."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Nous pouvons recevoir des instructions des personnes désignées par l'organisation, ou qui semblent raisonnablement autorisées à agir en son nom. Le client doit nous informer sans délai de tout changement des personnes autorisées à donner des instructions."}]}]}, "ai_assisted": false}, {"position": 2, "title": "2. Notre équipe juridique", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Un avocat responsable est désigné pour superviser le mandat et coordonner les services."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Selon la nature du dossier, Lex Canada Law peut faire appel à d'autres avocats, parajuristes, consultants, professionnels ou fournisseurs spécialisés. Leur intervention dépend notamment :"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "de la complexité du dossier ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "des compétences requises ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "des délais applicables ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "de la disponibilité des ressources ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "du besoin de recourir à une expertise externe."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Tous les professionnels qui travaillent au dossier sont tenus aux obligations applicables de confidentialité et de secret professionnel."}]}]}, "ai_assisted": false}, {"position": 3, "title": "3. Étendue du mandat", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "La nature et les limites de notre intervention sont précisées dans la lettre de mandat, la convention d'honoraires ou les communications écrites échangées avec le client."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Nous n'élargirons pas le mandat de façon importante sans les instructions ou l'autorisation du client."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Sauf entente expresse, notre intervention ne comprend pas automatiquement :"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "des conseils fiscaux ou comptables ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "l'évaluation financière d'une transaction ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "des conseils en placement ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "le droit d'un territoire étranger ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "le suivi continu des changements législatifs ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "les services qui ne sont pas expressément prévus au mandat."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Le client doit obtenir l'avis de ses comptables, fiscalistes, courtiers, consultants ou autres professionnels lorsque la situation l'exige."}]}]}, "ai_assisted": false}, {"position": 4, "title": "4. Responsabilités du client", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Le client s'engage à :"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "nous fournir des renseignements complets, exacts et à jour ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "nous transmettre rapidement les documents nécessaires ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "nous signaler toute échéance importante ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "nous informer de tout changement qui pourrait toucher le mandat ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "conserver les documents, courriels et éléments de preuve pertinents ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "collaborer raisonnablement avec notre équipe ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "examiner les documents qui lui sont remis ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "nous signaler sans délai toute erreur ou préoccupation."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Lex Canada Law ne peut être tenue responsable des conséquences découlant de renseignements incomplets, inexacts, tardifs ou retenus par le client ou par une personne agissant en son nom."}]}]}, "ai_assisted": false}, {"position": 5, "title": "5. Aucune garantie de résultat", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Lex Canada Law s'engage à fournir ses services avec compétence, diligence et professionnalisme. Toutefois, aucun résultat précis ne peut être garanti. Les décisions des tribunaux, des autorités gouvernementales, des organismes administratifs et des parties adverses échappent à notre contrôle."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Les estimations, opinions et stratégies communiquées au client représentent notre évaluation professionnelle au moment où elles sont formulées. Elles ne constituent pas une promesse de résultat."}]}]}, "ai_assisted": false}, {"position": 6, "title": "6. Conflits d'intérêts", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Avant d'accepter un mandat, Lex Canada Law peut effectuer les vérifications nécessaires pour déterminer s'il existe un conflit d'intérêts."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Notre cabinet représente plusieurs clients, dont certains peuvent exercer dans le même secteur ou avoir des intérêts commerciaux différents de ceux du client."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Sous réserve de nos obligations professionnelles, le fait de représenter une organisation ne nous empêche pas automatiquement de représenter d'autres clients dans des dossiers distincts."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Aucun renseignement confidentiel appartenant au client ne sera utilisé ou divulgué au profit d'un autre client sans autorisation ou sans fondement juridique applicable."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Si un conflit réel ou potentiel survient, nous prendrons les mesures requises conformément à nos obligations professionnelles. Celles-ci peuvent comprendre l'obtention d'un consentement, la mise en place de mesures de protection ou la fin du mandat."}]}]}, "ai_assisted": false}, {"position": 7, "title": "7. Honoraires, provisions et débours", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Les honoraires peuvent être établis selon :"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "un taux horaire ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "un montant forfaitaire ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "une provision périodique ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "une entente particulière ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "une combinaison de ces méthodes."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "La méthode de facturation applicable est précisée dans la lettre de mandat ou la convention d'honoraires."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Les estimations budgétaires sont fournies à titre indicatif seulement, sauf lorsqu'un prix forfaitaire est expressément convenu. Elles peuvent changer si l'étendue, la complexité, les délais ou les circonstances du dossier changent."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Le client demeure également responsable des taxes et débours applicables, notamment :"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "les frais gouvernementaux ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "les frais de dépôt ou d'enregistrement ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "les frais judiciaires ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "les services de messagerie ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "les frais de déplacement autorisés ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "les traductions ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "les rapports d'experts ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "les recherches spécialisées ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "les services de tiers."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Lex Canada Law peut demander une provision en fidéicommis avant de commencer ou de poursuivre le travail. Le client peut être appelé à reconstituer cette provision pendant le mandat."}]}]}, "ai_assisted": false}, {"position": 8, "title": "8. Facturation et paiement", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Les factures sont payables selon les modalités qui y sont indiquées ou qui figurent dans la convention d'honoraires."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "En cas de retard de paiement, Lex Canada Law peut, dans les limites permises par les règles professionnelles :"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "exiger le paiement immédiat des sommes dues ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "exiger la reconstitution de la provision ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "suspendre certains travaux ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "cesser d'agir pour le client ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "appliquer les intérêts prévus à l'entente applicable."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "La fin ou l'échec d'une transaction, d'une demande ou d'une procédure ne libère pas le client du paiement des services déjà rendus et des débours engagés."}]}]}, "ai_assisted": false}, {"position": 9, "title": "9. Utilisation de la technologie", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Lex Canada Law peut utiliser des technologies sécurisées pour faciliter la prestation de ses services, notamment :"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "des portails clients ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "la gestion électronique des dossiers ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "les signatures électroniques ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "la visioconférence ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "des outils de recherche juridique ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "l'analyse de documents ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "des services infonuagiques ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "des technologies d'intelligence artificielle."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Ces outils sont utilisés sous la supervision de professionnels du droit. Tout travail juridique destiné au client ou à une autorité compétente fait l'objet d'une révision professionnelle appropriée."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Nous choisissons nos outils en tenant compte de nos obligations de confidentialité, de sécurité et de protection des renseignements personnels."}]}]}, "ai_assisted": false}, {"position": 10, "title": "10. Communications électroniques", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sauf instruction contraire, le client autorise Lex Canada Law à communiquer par courriel, par téléphone, par visioconférence, par le portail client ou par tout autre moyen électronique raisonnable."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Les communications électroniques comportent certains risques, notamment l'interception, la fraude, les virus, les erreurs de destinataire et les délais de transmission."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Le client doit confirmer directement auprès de notre cabinet toute instruction inhabituelle, en particulier lorsqu'elle concerne :"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "un paiement ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "un changement de coordonnées bancaires ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "un transfert de fonds ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "la transmission de renseignements très sensibles ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "une demande urgente ou inhabituelle."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Lex Canada Law ne demandera jamais au client de modifier des instructions bancaires importantes sans un mécanisme de vérification approprié."}]}]}, "ai_assisted": false}, {"position": 11, "title": "11. Confidentialité et renseignements personnels", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Lex Canada Law recueille, utilise, conserve et communique les renseignements nécessaires pour fournir ses services, gérer le dossier et respecter ses obligations légales et professionnelles."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Les renseignements peuvent notamment servir à :"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "vérifier l'identité du client ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "détecter les conflits d'intérêts ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "fournir les services demandés ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "communiquer avec les autorités et les parties autorisées ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "produire les documents requis ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "gérer la facturation et les paiements ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "satisfaire aux exigences réglementaires."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Le traitement des renseignements personnels est également régi par la politique de confidentialité de Lex Canada Law."}]}]}, "ai_assisted": false}, {"position": 12, "title": "12. Fin du mandat", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Le client peut mettre fin au mandat par avis écrit."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Lex Canada Law peut également cesser d'agir lorsque les règles professionnelles le permettent, notamment en cas :"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "de conflit d'intérêts ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "de perte de confiance ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "de refus de collaborer ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "d'instructions illégales ou contraires à l'éthique ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "de renseignements faux ou trompeurs ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "de non-paiement des honoraires ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "d'impossibilité raisonnable de poursuivre le mandat."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "À la fin du mandat, les honoraires, taxes et débours impayés deviennent exigibles."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Sauf entente contraire, notre obligation d'agir prend fin lorsque le mandat est terminé, que le dossier est fermé ou que notre facture finale est émise. Nous n'avons aucune obligation de suivre l'évolution future du droit ni de rappeler au client des échéances survenant après la fermeture du dossier."}]}]}, "ai_assisted": false}, {"position": 13, "title": "13. Conservation des dossiers", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Les documents du dossier sont conservés conformément aux exigences légales, professionnelles et administratives applicables."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "À la fin de la période de conservation, certains documents peuvent être détruits de façon sécuritaire, sauf si une conservation plus longue est exigée par la loi ou convenue avec le client."}]}]}, "ai_assisted": false}, {"position": 14, "title": "14. Droit applicable", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Les présentes conditions sont régies par les lois de la province de la Nouvelle-Écosse et les lois fédérales du Canada qui s'y appliquent, sous réserve des règles professionnelles régissant les services juridiques concernés."}]}]}, "ai_assisted": false}, {"position": 15, "title": "Acceptation des présentes conditions", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "En signant une lettre de mandat, en acceptant une convention d'honoraires ou en demandant à Lex Canada Law de commencer les services convenus, le client reconnaît avoir lu les présentes conditions et accepte qu'elles régissent la prestation des services, sous réserve de toute entente écrite particulière. Pour toute question concernant ces conditions ou votre dossier, veuillez communiquer avec l'avocat responsable de votre mandat."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Client : "}, {"type": "field", "attrs": {"key": "client.name"}}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Date : "}, {"type": "field", "attrs": {"key": "date.today"}}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Signature : ______________________________"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "© 2026 Lex Canada Juris Corp. Tous droits réservés. Lex Canada Law est une marque de commerce de Lex Canada Juris Corp."}]}]}, "ai_assisted": false}]$json$::jsonb, $json$[]$json$::jsonb);
insert into public.contract_templates (id, name, description, domain, language, signing, status, needs_review, current_version, is_mock)
  values ('10000000-0000-4000-8000-0000000c0004', 'Conditions générales de service — Particuliers et familles', 'Traduction française à faire valider par un avocat avant publication.', 'legal', 'fr', 'portal', 'draft', true, 1, false);
insert into public.contract_template_versions (template_id, version, sections, line_items)
  values ('10000000-0000-4000-8000-0000000c0004', 1, $json$[{"position": 0, "title": "Introduction", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Merci d'avoir choisi Lex Canada Law pour vous accompagner dans vos affaires juridiques. Les présentes conditions générales décrivent le cadre dans lequel notre cabinet fournit ses services. Elles complètent la lettre de mandat, la convention d'honoraires ou toute autre entente particulière conclue avec le client. En cas d'incompatibilité, les modalités de la lettre de mandat ou de l'entente particulière prévalent."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Client : "}, {"type": "field", "attrs": {"key": "client.name"}}, {"type": "text", "text": " · Dossier : "}, {"type": "field", "attrs": {"key": "matter.number"}}, {"type": "text", "text": " · Avocat responsable : "}, {"type": "field", "attrs": {"key": "lawyer.name"}}]}]}, "ai_assisted": false}, {"position": 1, "title": "1. Notre engagement envers vous", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Lex Canada Law accompagne les particuliers et les familles avec compétence, clarté, respect et confidentialité. Notre rôle est de vous expliquer vos options, de vous aider à comprendre les risques et de faire valoir vos intérêts dans le cadre du mandat qui nous est confié."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Vous travaillerez avec un avocat responsable de votre dossier. D'autres professionnels peuvent aussi intervenir lorsque leur expertise est requise."}]}]}, "ai_assisted": false}, {"position": 2, "title": "2. Formation de la relation avocat-client", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Une consultation, un échange de courriels ou la transmission de documents ne signifie pas automatiquement que Lex Canada Law a accepté de vous représenter."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "La relation avocat-client ne commence que lorsque :"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "le cabinet a confirmé l'acceptation du mandat ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "les vérifications d'identité et de conflits ont été effectuées ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "la convention d'honoraires ou la lettre de mandat a été acceptée ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "la provision demandée, le cas échéant, a été versée."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Avant cette confirmation, vous demeurez responsable de vos propres délais et de la protection de vos droits."}]}]}, "ai_assisted": false}, {"position": 3, "title": "3. Étendue de notre intervention", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Notre mandat se limite aux services décrits dans votre lettre de mandat ou votre convention d'honoraires."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Par exemple, un mandat portant sur une demande d'immigration ne comprend pas automatiquement :"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "un appel ou un contrôle judiciaire ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "une nouvelle demande après un refus ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "une audience non prévue ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "un dossier concernant un autre membre de la famille ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "des conseils fiscaux ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "une procédure civile distincte."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Tout service supplémentaire exige une nouvelle autorisation et peut entraîner des honoraires additionnels."}]}]}, "ai_assisted": false}, {"position": 4, "title": "4. Votre collaboration", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Pour bien vous représenter, nous avons besoin de renseignements complets et exacts, fournis à temps."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Vous devez notamment :"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "répondre honnêtement à nos questions ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "fournir tous les documents pertinents ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "nous informer de vos antécédents et de tout refus antérieur ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "respecter les délais communiqués ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "relire les formulaires et déclarations avant de les signer ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "nous aviser immédiatement de tout changement d'adresse, de statut ou de situation ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "conserver les originaux de vos documents importants ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "nous transmettre toute communication reçue d'une autorité, d'un tribunal ou d'une partie adverse."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Le fait de cacher ou d'omettre des renseignements importants peut compromettre votre dossier et nous obliger à cesser d'agir."}]}]}, "ai_assisted": false}, {"position": 5, "title": "5. Services d'immigration", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "En matière d'immigration, le client reconnaît que les décisions relèvent notamment d'Immigration, Réfugiés et Citoyenneté Canada, de l'Agence des services frontaliers du Canada, de la Commission de l'immigration et du statut de réfugié, des tribunaux ou des programmes provinciaux."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Les délais de traitement peuvent changer et échappent au contrôle de Lex Canada Law."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Nous ne pouvons pas garantir :"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "l'approbation d'une demande ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "la délivrance d'un visa ou d'un permis ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "l'obtention de la résidence permanente ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "l'acceptation d'un appel ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "une date de décision précise ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "l'absence d'entrevue, d'enquête ou de demande de documents supplémentaires."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Notre responsabilité est de préparer, de conseiller et de représenter le client conformément au mandat convenu."}]}]}, "ai_assisted": false}, {"position": 6, "title": "6. Litiges et procédures", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Dans une affaire contentieuse, le résultat peut dépendre de la preuve, des témoignages, des règles de procédure, de la position de la partie adverse et de la décision du tribunal."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Le client comprend qu'une procédure peut entraîner :"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "des délais ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "des coûts supplémentaires ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "des négociations ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "une médiation ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "une audience ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "une décision défavorable ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "une condamnation aux dépens."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Nous conseillerons le client sur les options raisonnables, mais la décision finale de régler ou de poursuivre l'affaire appartient au client."}]}]}, "ai_assisted": false}, {"position": 7, "title": "7. Planification successorale", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Les testaments, procurations, directives personnelles et autres documents successoraux sont préparés à partir des renseignements fournis par le client."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Le client doit nous informer de sa situation familiale, de ses biens, de ses obligations, de ses intentions et de toute circonstance particulière pertinente."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Après la fin du mandat, Lex Canada Law n'a aucune obligation de mettre automatiquement les documents à jour. Le client devrait demander une révision après un changement important, notamment :"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "un mariage ou une séparation ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "une naissance ou une adoption ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "un décès ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "l'acquisition ou la vente d'un bien important ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "un déménagement dans une autre province ou un autre pays ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "un changement important du droit."}]}]}]}]}, "ai_assisted": false}, {"position": 8, "title": "8. Honoraires et débours", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Nos honoraires peuvent être forfaitaires ou calculés selon le temps consacré au dossier. La méthode applicable est précisée avant le début du mandat."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Des honoraires additionnels peuvent s'appliquer si :"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "le mandat est élargi ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "de nouveaux faits surviennent ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "le client demande un traitement urgent ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "une audience ou une entrevue devient nécessaire ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "des documents supplémentaires doivent être préparés ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "une nouvelle procédure est entreprise."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Les débours gouvernementaux, judiciaires, administratifs et autres ne sont pas inclus, sauf indication contraire."}]}]}, "ai_assisted": false}, {"position": 9, "title": "9. Paiement", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Une provision peut être exigée avant le début des travaux. Les sommes déposées en fidéicommis sont appliquées aux factures conformément aux règles applicables."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Les factures doivent être payées selon les modalités convenues. Un défaut de paiement peut entraîner la suspension ou la fin du mandat, lorsque les règles professionnelles le permettent."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Les honoraires demeurent payables même si la demande est refusée, si la procédure échoue ou si le client décide de ne pas poursuivre le dossier."}]}]}, "ai_assisted": false}, {"position": 10, "title": "10. Confidentialité", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Les renseignements confiés à Lex Canada Law sont protégés par nos obligations de confidentialité et, lorsque les conditions légales sont réunies, par le secret professionnel de l'avocat."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Dans un mandat conjoint — notamment lorsque nous représentons plusieurs membres d'une même famille —, les renseignements pertinents au dossier peuvent devoir être partagés entre les clients représentés."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Si un conflit survient entre les clients d'un mandat conjoint, Lex Canada Law peut être tenue de cesser de représenter une ou plusieurs des personnes concernées."}]}]}, "ai_assisted": false}, {"position": 11, "title": "11. Protection des renseignements personnels", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Nous recueillons seulement les renseignements nécessaires pour fournir nos services et respecter nos obligations."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Selon le dossier, certains renseignements peuvent être communiqués aux tribunaux, aux autorités gouvernementales, à des experts, à des traducteurs ou à d'autres parties autorisées."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Pour en savoir plus, le client peut consulter la politique de confidentialité de Lex Canada Law."}]}]}, "ai_assisted": false}, {"position": 12, "title": "12. Technologie et intelligence artificielle", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Lex Canada Law peut utiliser des outils technologiques pour améliorer la gestion et la qualité de ses services, notamment pour :"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "gérer les dossiers ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "communiquer avec les clients ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "effectuer des recherches juridiques ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "analyser ou organiser des documents ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "préparer des projets de documents ;"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "obtenir des signatures électroniques."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Toute utilisation d'un outil technologique demeure soumise aux obligations de confidentialité et de compétence professionnelle. Les documents et conseils juridiques produits à l'aide de ces outils sont révisés par un professionnel du droit avant tout usage officiel."}]}]}, "ai_assisted": false}, {"position": 13, "title": "13. Communications et sécurité", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Le client autorise les communications électroniques aux coordonnées qu'il fournit."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Le client doit informer Lex Canada Law si une adresse courriel ou un numéro de téléphone n'est pas sécurisé, est partagé avec une autre personne ou ne doit pas servir à transmettre des renseignements confidentiels."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Aucun paiement ni changement de coordonnées bancaires ne devrait être effectué sur la seule foi d'un courriel inattendu. Le client doit communiquer directement avec le cabinet pour vérifier toute instruction financière inhabituelle."}]}]}, "ai_assisted": false}, {"position": 14, "title": "14. Fin du mandat", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Le client peut mettre fin au mandat par avis écrit."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Lex Canada Law peut cesser d'agir conformément à ses obligations professionnelles, notamment en cas de conflit, de non-paiement, de manque de collaboration, de perte de confiance ou d'instructions contraires à la loi."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Les honoraires et débours engagés jusqu'à la fin du mandat demeurent payables."}]}]}, "ai_assisted": false}, {"position": 15, "title": "15. Fermeture et conservation du dossier", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "À la fin du mandat, Lex Canada Law ferme le dossier et conserve les documents conformément à sa politique de conservation et aux exigences professionnelles applicables."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Une fois le dossier fermé, le cabinet n'est pas tenu de suivre l'évolution future du droit, les nouvelles échéances ou les changements de la situation du client, à moins qu'un nouveau mandat ne soit expressément accepté."}]}]}, "ai_assisted": false}, {"position": 16, "title": "16. Droit applicable", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Les présentes conditions sont régies par les lois de la Nouvelle-Écosse et les lois fédérales du Canada qui s'y appliquent, sous réserve des règles professionnelles pertinentes."}]}]}, "ai_assisted": false}, {"position": 17, "title": "Acceptation des présentes conditions", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "En signant une lettre de mandat, en acceptant une convention d'honoraires ou en demandant à Lex Canada Law de commencer les services convenus, le client reconnaît avoir lu les présentes conditions et accepte qu'elles régissent la prestation des services, sous réserve de toute entente écrite particulière. Pour toute question concernant ces conditions ou votre dossier, veuillez communiquer avec l'avocat responsable de votre mandat."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Client : "}, {"type": "field", "attrs": {"key": "client.name"}}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Date : "}, {"type": "field", "attrs": {"key": "date.today"}}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Signature : ______________________________"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "© 2026 Lex Canada Juris Corp. Tous droits réservés. Lex Canada Law est une marque de commerce de Lex Canada Juris Corp."}]}]}, "ai_assisted": false}]$json$::jsonb, $json$[]$json$::jsonb);
